import { useField, useForm } from '@pyreon/form'
import { z } from 'zod'

const schema = z.object({
  email: z.string().email('Enter a valid email'),
  password: z.string().min(8, 'At least 8 characters'),
})

function SignUp() {
  const form = useForm({
    initialValues: { email: '', password: '' },
    schema,
    onSubmit: async (values) => {
      const res = await api.signup(values)
      if (res.emailTaken) form.setErrors({ email: 'Already registered' })
    },
  })
  const email = useField(form, 'email')
  const password = useField(form, 'password')

  return (
    <form onSubmit={form.handleSubmit}>
      <input {...email.register()} />
      {() => email.showError() && <span>{email.error()}</span>}
      <input type="password" {...password.register()} />
      {() => password.showError() && <span>{password.error()}</span>}
      <button disabled={form.isSubmitting}>Sign up</button>
    </form>
  )
}

