import { nestValues, useForm } from '@pyreon/form'

function ProfileForm() {
  const form = useForm({
    initialValues: { name: '', 'address.city': '', 'address.zip': '' },
    validators: {
      'address.zip': (zip) => (/^\d{5}$/.test(zip) ? undefined : 'Five digits'),
    },
    // values stay flat; nest them at the API boundary
    onSubmit: (values) => api.saveProfile(nestValues(values)),
  })

  return (
    <form onSubmit={form.handleSubmit}>
      <input {...form.register('name')} />
      <input {...form.register('address.city')} />
      <input {...form.register('address.zip')} />
      <span>{form.fields['address.zip'].error()}</span>
      <button>Save</button>
    </form>
  )
}

import { For } from '@pyreon/core'
import { useFieldArray } from '@pyreon/form'

function Invites() {
  const emails = useFieldArray<string>([''])

  return (
    <ul>
      <For each={emails.items} by={(item) => item.key}>
        {(item) => (
          <li>
            <input
              value={item.value()}
              onInput={(e) => item.value.set(e.currentTarget.value)}
            />
            <button type="button" onClick={() => emails.remove(emails.items().indexOf(item))}>
              Remove
            </button>
          </li>
        )}
      </For>
      <button type="button" onClick={() => emails.append('')}>Add another</button>
    </ul>
  )
}

import { useForm } from '@pyreon/form'
type Post = { title: string; body: string }

function EditPost(props: { post: Post }) {
  const form = useForm({
    initialValues: props.post,
    onSubmit: async (values) => {
      const saved = await api.savePost(values)
      form.reset(saved) // the server's copy becomes the new clean baseline
    },
  })

  return (
    <form onSubmit={form.handleSubmit}>
      <input {...form.register('title')} />
      <textarea {...form.register('body')} />
      <button disabled={() => !form.isDirty() || form.isSubmitting()}>Save</button>
    </form>
  )
}
